def solve(data):
    packages = data.get('packages', {})
    roots = data.get('roots', {})
    names = sorted(packages)

    if any(name not in packages for name in roots):
        return {'error': 'unsatisfiable'}

    root_ranges = {name: (bounds[0], bounds[1])
                   for name, bounds in roots.items()}
    rows_by_name = {}
    for name, rows in packages.items():
        rows_by_name[name] = [
            row for row in rows
            if name not in root_ranges or
            root_ranges[name][0] <= row['version'] <= root_ranges[name][1]
        ]

    best_vector = None
    best_versions = None

    def search(assigned, required):
        nonlocal best_vector, best_versions

        pending = required - assigned.keys()
        if not pending:
            vector = tuple(assigned[name]['version'] if name in assigned else -1
                           for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = {name: assigned[name]['version']
                                 for name in sorted(assigned)}
            return

        if best_vector is not None:
            upper = []
            for name in names:
                if name in assigned:
                    upper.append(assigned[name]['version'])
                else:
                    versions = [row['version'] for row in rows_by_name[name]]
                    upper.append(max([-1] + versions))
            if tuple(upper) <= best_vector:
                return

        name = min(pending)
        for row in choose(rows_by_name.get(name, [])):
            deps = row.get('deps', [])
            if any(dep not in packages for dep in deps):
                continue
            next_assigned = dict(assigned)
            next_assigned[name] = row
            search(next_assigned, required | set(deps))

    search({}, set(roots))
    if best_versions is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_versions}
